        if candidate is None:
            # scan receptacles via admissible go to commands
            adm = env.admissible()
            goto_cmds = [c for c in adm if c.startswith('go to ')]
            # priority: receptacles from initial list
            ordered = []
            for r in recs:
                g = 'go to ' + r
                if g in goto_cmds and g not in ordered:
                    ordered.append(g)
            for r in recs:
                pass
            for g in ordered:
                if steps >= max_steps:
                    break
                r = step(g)
                if r is None:
                    continue
                c2 = find_obj_loc()
                if c2 is not None:
                    candidate = c2
                    break
        # now go to candidate and take
        if candidate is not None:
            step('go to ' + candidate)
            step('take ' + obj + ' from ' + candidate)
        else:
            # try take from current location name
            adm = env.admissible()
            takes = [c for c in adm if c.startswith('take ' + obj)]
            if takes:
                # pick first
                step(takes[0])

    # cool if needed (goal contains cool)
    goal_lower = goal.lower()
    if 'cool' in goal_lower:
        # need a fridge or similar; go to fridge 1 if exists
        adm = env.admissible()
        cool_cmds = [c for c in adm if c.startswith('cool ' + obj)]
        if cool_cmds:
            step(cool_cmds[0])
        else:
            # go to a fridge
            fridge_candidates = [r for r in recs if 'fridge' in r.lower()]
            for fr in fridge_candidates:
                if steps >= max_steps:
                    break
                r = step('go to ' + fr)
                if r is None:
                    continue
                adm = env.admissible()
                cool_cmds = [c for c in adm if c.startswith('cool ' + obj)]
                if cool_cmds:
                    step(cool_cmds[0])
                    break

    # move to destination
    # destination may be a receptacle; find it
    def find_dest():
        # search observation for destination name
        t = env.observation
        # if exactly "shelf" match "shelf 1"
        for mm in re.finditer(r'\b' + re.escape(dest_key) + r' \d+\b', t, re.I):
            return mm.group(0)
        return None

    drec = find_dest()
    if drec is None:
        # try from initial list
        for r in recs:
            if dest_key in r.lower():
                drec = r
                break
    if drec is None:
        drec = dest  # fallback

    step('go to ' + drec)
    adm = env.admissible()
    moves = [c for c in adm if c.startswith('move ' + obj)]
    if moves:
        step(moves[0])
    else:
        # maybe no need
        pass
